mapper.select:
select la.id, la.is_hot, la.name, la.remark, la.banner_img, la.limit_type, la.limit_num, la.join_num, la.type, la.task_type, la.val, la.color_msg, la.start_time, la.end_time, la.cover_img, la.introduce_img, la.status, la.create_user_id, la.update_user_id, la.create_time, la.update_time, la.create_type from la_activity la
and la.is_delete = 0
and la.name like concat('%',#{param.name},'%')
and la.start_time > #{param.nowDate}
and la.start_time < #{param.nowDate} and la.end_time > #{param.nowDate}
and la.end_time < #{param.nowDate}
and la.content like concat('%',#{param.content},'%')
and la.remark like concat('%',#{param.remark},'%')
and la.limit_type = #{param.limitType}
and la.limit_num = #{param.limitNum}
and la.join_num = #{param.joinNum}
and la.type = #{param.type}
and la.val like concat('%',#{param.val},'%')
and la.start_time = #{param.startTime}
and la.end_time = #{param.endTime}
and la.cover_img like concat('%',#{param.coverImg},'%')
and la.introduce_img like concat('%',#{param.introduceImg},'%')
and la.create_user_id = #{param.createUserId}
and la.update_user_id = #{param.updateUserId}
and la.create_type = #{param.createType}
order by la.id desc
